'use client';

import { MenuOption } from '../useMenuDetail';
import styles from './OptionsInfo.module.css';

interface OptionsInfoProps {
    options: MenuOption[];
}

export default function OptionsInfo({ options }: OptionsInfoProps) {
    const formatPrice = (priceDelta: number) => {
        if (priceDelta === 0) return '무료';
        const prefix = priceDelta > 0 ? '+' : '';
        return `${prefix}${new Intl.NumberFormat('ko-KR').format(priceDelta)}원`;
    };

    if (!options || options.length === 0) {
        return (
            <section className={styles.optionsSection}>
                <h3 className={styles.sectionTitle}>옵션</h3>
                <p className={styles.emptyMessage}>등록된 옵션이 없습니다.</p>
            </section>
        );
    }

    return (
        <section className={styles.optionsSection}>
            <h3 className={styles.sectionTitle}>옵션</h3>
            <div className={styles.optionList}>
                {options.map((option) => (
                    <div key={option.id} className={styles.optionGroup}>
                        <div className={styles.optionHeader}>
                            <span className={styles.optionName}>{option.name}</span>
                            <div className={styles.optionTags}>
                                <span className={`${styles.tag} ${option.required ? styles.required : styles.optional}`}>
                                    {option.required ? '필수' : '선택'}
                                </span>
                                <span className={styles.tag}>
                                    {option.type === 'radio' ? '단일 선택' : '다중 선택'}
                                </span>
                            </div>
                        </div>
                        <div className={styles.optionItems}>
                            {option.items.map((item) => (
                                <div key={item.id} className={styles.optionItem}>
                                    <span className={styles.itemName}>{item.name}</span>
                                    <span className={styles.itemPrice}>
                                        {formatPrice(item.priceDelta)}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </section>
    );
}
